import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  FaShoppingCart,
  FaChevronLeft,
  FaChevronRight,
  FaHeart,
  FaShoppingBag,
  FaRegHeart
} from 'react-icons/fa';
import ProductCard from '../../Components/ProductCard/ProductCard';
import RatingStars from '../../Components/RatingStars/RatingStars';
import ProductTabs from '../../Components/ProductTabs/ProductTabs'; 
import Image3 from '../../Assets/Image3.png';
import Image2 from '../../Assets/Image2.png';
import Image1 from '../../Assets/Image1.png';
import R1 from '../../Assets/R1.png';
import R2 from '../../Assets/R2.png';
import R3 from '../../Assets/R3.png';
import R4 from '../../Assets/R4.png';
import './ProductReturns.css';

const ProductReturns = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const defaultProduct = {
    id: 1,
    name: 'Noah Yellow overcoat',
    price: 5000.0,
    inStock: true,
    colors: ['orange', 'red', 'black'],
    sizes: ['M', 'L', 'XL', 'XXL'],
    images: [Image3, Image2, Image1],
    description: 'This is a stylish Noah Yellow Overcoat designed with bold black and gray accents, adding a modern edge to its vibrant yellow base. Perfect for colder seasons, it blends functionality with high fashion. The product offers a variety of sizes and color choices.',
    rating: 4.5,
    reviewCount: 18
  };

  const product = location.state?.product || defaultProduct;

  const [selectedSize, setSelectedSize] = useState(product.sizes?.[0] || 'M');
  const [selectedColor, setSelectedColor] = useState(product.colors?.[0] || 'orange');
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [quantity, setQuantity] = useState(1);
  const [isFavorite, setIsFavorite] = useState(false);
  const [activeTab, setActiveTab] = useState('returns');

  const recommendedProducts = [
    { 
      id: 2, 
      name: 'Black Pins', 
      price: 2500.0, 
      rating: 5, 
      reviewCount: 121,
      image: Image1
    },
    { 
      id: 3, 
      name: 'Winter Jersey', 
      price: 500.0, 
      rating: 5, 
      reviewCount: 121,
      image: R1
    },
    { 
      id: 4, 
      name: 'Over Coat', 
      price: 10000.0, 
      rating: 5, 
      reviewCount: 121,
      image: R2
    },
    { 
      id: 5, 
      name: 'Summer dress', 
      price: 1500.0, 
      rating: 5, 
      reviewCount: 121,
      image: R3
    },
    { 
      id: 6, 
      name: 'Full kit', 
      price: 9000.0, 
      rating: 5, 
      reviewCount: 121,
      image: R4
    }
  ];

  const nextImage = () => {
    setCurrentImageIndex((prev) =>
      prev === product.images.length - 1 ? 0 : prev + 1
    );
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) =>
      prev === 0 ? product.images.length - 1 : prev - 1
    );
  };

  const handleAddToCart = () => {
    navigate('/cart', {
      state: {
        product: {
          ...product,
          selectedSize,
          selectedColor,
          quantity
        }
      }
    });
  };

  const handleBuyNow = () => {
    navigate('/checkout', {
      state: {
        product: {
          ...product,
          selectedSize,
          selectedColor,
          quantity
        }
      }
    });
  };

  return (
    <div className="returns-page">
      <div className="returns-container">
        <div className="returns-main">
          {/* Image Gallery */}
          <div className="returns-images">
            <div className="returns-main-image">
              <img
                src={product.images[currentImageIndex]}
                alt={product.name}
                className="returns-main-img"
                onError={(e) => {
                  e.target.src = '/images/product/placeholder.jpg';
                }}
              />
              <button className="returns-nav-button returns-prev" onClick={prevImage}>
                <FaChevronLeft />
              </button>
              <button className="returns-nav-button returns-next" onClick={nextImage}>
                <FaChevronRight />
              </button>
            </div>
            <div className="returns-image-dots-container">
              {product.images.map((_, index) => (
                <span
                  key={index}
                  className={`returns-dot ${currentImageIndex === index ? 'returns-active' : ''}`}
                  onClick={() => setCurrentImageIndex(index)}
                />
              ))}
            </div>
          </div>

          {/* Product Details */}
          <div className="returns-details">
            <div className="returns-rating-favorite-container">
              <RatingStars rating={product.rating} size="large" />
              <button
                className="returns-favorite-button-top"
                onClick={() => setIsFavorite(!isFavorite)}
              >
                {isFavorite ? <FaHeart className="returns-filled" /> : <FaRegHeart />}
              </button>
            </div>

            <h1 className="returns-title">{product.name}</h1>
            <p className="returns-sub-description">New Exclusive wear</p>

            <div className="returns-price-stock">
              <span className="returns-price">Rs. {product.price.toFixed(2)}</span>
              <span className="returns-stock">{product.inStock ? 'In stock' : 'Out of stock'}</span>
            </div>

            {/* Color Selector */}
            <div className="returns-color-selector">
              <span className="returns-color-label">Color</span>
              <div className="returns-color-options">
                {product.colors.map((color) => (
                  <div
                    key={color}
                    className={`returns-color-option-wrapper ${
                      selectedColor === color ? 'returns-color-selected' : ''
                    }`}
                    onClick={() => setSelectedColor(color)}
                  >
                    <div
                      className="returns-color-option"
                      style={{
                        backgroundColor: color.toLowerCase()
                      }}
                      aria-label={color}
                    />
                  </div>
                ))}
              </div>
            </div>

            {/* Size Selector */}
            <div className="returns-size-selector">
              <span className="returns-size-label">Size</span>
              <div className="returns-size-options">
                {product.sizes.map((size) => (
                  <button
                    key={size}
                    className={`returns-size-option ${selectedSize === size ? 'returns-size-option-selected' : ''}`}
                    onClick={() => setSelectedSize(size)}
                  >
                    {size}
                  </button>
                ))}
              </div>
            </div>

            {/* Quantity Control */}
            <div className="returns-quantity-control">
              <div className="returns-quantity-selector">
                <button 
                  onClick={() => setQuantity(Math.max(1, quantity - 1))}
                  aria-label="Decrease quantity"
                >
                  -
                </button>
                <span aria-live="polite">{quantity}</span>
                <button 
                  onClick={() => setQuantity(quantity + 1)}
                  aria-label="Increase quantity"
                >
                  +
                </button>
              </div>
            </div>
            
            {/* Action Buttons */}
            <div className="returns-product-actions">
              <button className="returns-add-to-cart" onClick={handleAddToCart}>
                Add To Cart
              </button>
              <button className="returns-buy-now" onClick={handleBuyNow}>
                Buy Now
              </button>
            </div>

            {/* Secure Checkout */}
            <div className="returns-secure-checkout">
              <div className="returns-secure-icons">
                 <img
                                  src= {visa}
                alt= "Secure Payment"
                                />
                                <img
                                  src= {pay}
                                  alt= "Secure Payment"
                                />
              </div>
              <p>Guarantee safe & secure checkout</p>
            </div>
          </div>
        </div>

        {/* Tabs Section */}
        <div className="returns-tabs-section">
          <ProductTabs activeTab={activeTab} setActiveTab={setActiveTab} />
          <div className="returns-tab-content">
            {activeTab === 'description' && (
              <div>
                <h2>Product Description</h2>
                <p>{product.description}</p>
              </div>
            )}
            {activeTab === 'review' && (
              <div>
                <h2>Customer Reviews</h2>
                <p>No reviews yet.</p>
              </div>
            )}
            {activeTab === 'returns' && (
              <div className="returns-content">
                <h2>RETURN</h2>
                <div className="returns-policy-section">
                  <p>
                    Our dispatch head time is 7 working days for orders that include both ready-to-strip 
                    and made-on-order pieces. If you would like the ready-to-strip pieces to be dispatched 
                    early, please mention in the NOTES section of checkout.
                  </p>
                  <p>
                    Returns must be initiated within 3 days of delivery. Returns include exchange of size, 
                    style or credit note only.
                  </p>
                  <p>
                    COD, returns and exchanges are not possible on customized garments.
                  </p>
                </div>

                <h2>SHIPPING</h2>
                <div className="returns-policy-section">
                  <p>Enjoy free shipping on all orders.</p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Recommended Products */}
        <div className="returns-recommended-products">
          <h2>Recommended</h2>
          <p className="returns-subtitle">You might want to take a look at these.</p>
          <div className="returns-product-grid">
            {recommendedProducts.map((p) => (
              <ProductCard key={p.id} product={p} variant="small" />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductReturns;
